'use strict';

const fs = require('fs');
const path = require('path');
const { transformSync } = require('esbuild');
const { scriptManifest, bundleConfig } = require('./script-manifest');

const root = path.resolve(__dirname, '..');
const outputPath = path.join(root, bundleConfig.output);

function buildBundle() {
	// A non-directive statement keeps file-level directives from making the bundle strict.
	return '/* Generated by tools/build-bundle.js; do not edit. */\n0;\n' + scriptManifest.boot.map(file => {
		const source = fs.readFileSync(path.join(root, file), 'utf8');
		// No format or wrapper: other classic scripts depend on these top-level names.
		const { code } = transformSync(source, { minify: true, treeShaking: false, sourcefile: file });
		return `// ${file}\n${code};\n`;
	}).join('');
}

function main(args = process.argv.slice(2)) {
	if (args.some(arg => arg !== '--check')) throw new Error('Usage: node tools/build-bundle.js [--check]');
	const output = buildBundle();
	const current = fs.existsSync(outputPath) ? fs.readFileSync(outputPath, 'utf8') : null;
	if (args.includes('--check')) {
		if (output !== current) {
			process.stderr.write('Boot bundle is out of date; run node tools/build.js\n');
			return 1;
		}
	} else if (output !== current) {
		fs.mkdirSync(path.dirname(outputPath), { recursive: true });
		fs.writeFileSync(outputPath, output);
	}
	process.stdout.write(`Boot bundle ${args.includes('--check') ? 'verified' : 'built'}: ${Buffer.byteLength(output)} bytes\n`);
	return 0;
}

if (require.main === module) {
	try { process.exitCode = main(); }
	catch (error) { process.stderr.write(`${error.message}\n`); process.exitCode = 1; }
}

module.exports = { buildBundle, main };
